  vec2 me=gDR(ivec2(0)); vec2 d=normalize(uSun+1e-4); d.y=-d.y;
  for(int i=1;i<=8;i++){ if(float(i)>len) break;
    vec2 o=gDR(ivec2(floor(d*float(i)+0.5)));
