  return 0.0;
}
float edgeOut(float th){
  if(gInfo(ivec2(0)).a>0.75) return 0.0;
  int t=int(th+0.5);
  for(int y=-2;y<=2;y++) for(int x=-2;x<=2;x++){
    if(abs(x)+abs(y)>t || (x==0&&y==0)) continue;
    if(gInfo(ivec2(x,y)).a>0.75) return 1.0;
  }
  return 0.0;
